    if not s:
        raise ValueError('empty string')
    total = 0
    for i, ch in enumerate(s):
        if ch not in values:
            raise ValueError('invalid symbol')
        if i < len(s) - 1 and values[ch] < values[s[i + 1]]:
            total -= values[ch]
        else:
            total += values[ch]
    return total
